## 3️⃣ `config/mercadopago.js`

```js
require('dotenv').config();
const { Client } = require('@mercadopago/node-sdk');

const client = new Client({
  access_token: process.env.MERCADO_PASON_ACCESS_TOKEN, // obtido após criar app
});

async function getAccessToken() {
  if (!process.env.MERCADO_PASON_ACCESS_TOKEN) throw new Error('Sem token');
  return process.env.MERCADO_PASON_ACCESS_TOKEN;
}

async function criarCobrancaPix(valor, descricao, chavePix) {
  const res = await fetch('https://api.mercadopago.com/v1/payments', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${await getAccessToken()}`,
    },
    body: JSON.stringify({
      amount: parseFloat(valor.replace('R$', '').replace('.', ',')).replace(',', '.'),
      currency_id: 'BRL',
      description: descricao,
      source: {
        pix: {
          // opcional: link direto do QR Pix da MP
        },
      },
      external_reference: chavePix || null,
      metadata: {
        evento: 'presente-casamento',
        noivos: JSON.stringify(['Nome1', 'Nome2']),
      },
    }),
  });
  const data = await res.json();
  if (!res.ok) throw new Error(data.message || 'Falha MP');
  return data.id; // payment_id
}
```

