## 4️⃣ `src/db.js` — SQLite

```js
const Database = require('better-sqlite3');
const db = new Database('./data/casamento.db');

db.pragma('journal_mode = WAL');
db.pragma('foreign_keys = ON');

db.exec(`
  CREATE TABLE IF NOT EXISTS mensagens (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    texto TEXT NOT NULL,
    nome_enviador TEXT,
    pix_pagamento TEXT UNIQUE,
    criado_em DATETIME DEFAULT CURRENT_TIMESTAMP
  );

  CREATE TABLE IF NOT EXISTS presentes (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    payment_id TEXT UNIQUE NOT NULL,
    valor REAL,
    status TEXT DEFAULT 'aguardando',
    criado_em DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`);

function inserirMensagem(msg) {
  db.prepare(
    `INSERT INTO mensagens (texto, nome_enviador, pix_pagamento)
     VALUES (?, ?, ?)`
  ).run(msg.texto, msg.nome, msg.pix);
}

function ultimas3() {
  return db.prepare('SELECT * FROM mensagens ORDER BY criado_em DESC LIMIT 3').all();
}

function atualizarStatusPresente(id) {
  db.prepare('UPDATE presentes SET status = ? WHERE id = ?')
    .run('confirmado', id).run();
}

module.exports = { db, inserirMensagem, ultimas3, atualizarStatusPresente };
```

