```js
require('dotenv').config();
const express = require('express');
const cors = require('cors');
const http = require('http');
const { Server } = require('ws');
const path = require('path');
const { db, inserirMensagem, ultimas3, atualizarStatusPresente } = require('./db');
const { criarCobrancaPix } = require('./pix');

const app = express();
app.use(cors({ origin: process.env.SITE_URL || '*' }));
app.use(express.json());
app.use(express.static(path.join(__dirname, '..', 'public')));

// Estado global do QR (qual presente foi pago)
let qrAtivo = true;
let presentePagoId = null;

const server = http.createServer(app);
const wss = new Server(server, { port: Number(process.env.PORT || 3000) });

wss.on('connection', (ws) => {
  ws.send(JSON.stringify({ tipo: 'status', qr: qrAtivo, ultimas: ultimas3() }));
});

// Rotas REST
app.get('/', (req, res) => {
  res.sendFile(path.join(__dirname, '..', 'public', 'index.html'));
});

app.get('/form', (req, res) => {
  res.sendFile(path.join(__dirname, '..', 'public', 'form.html'));
});

app.post('/api/enviar', async (req, res) => {
  const { texto, nome, pixPagamento } = req.body;
  if (!texto || !nome) return res.status(400).json({ erro: 'Campos obrigatórios' });

  try {
    // Se já houve pagamento vinculado, aceita mensagem associada
    const existing = await db.prepare('SELECT pix_pagamento FROM mensagens WHERE pix_pagamento = ?').get(pixPagamento);
    if (existing && existente.pix_pagamento !== pixPagamento) {
      // mesmo pix mas mensagem nova? permitimos atualização
      await db.prepare('UPDATE mensagens SET texto = ?, nome_enviador = ? WHERE pix_pagamento = ?')
        .run(texto, nome, pixPagamento);
    } else {
      inserirMensagem({ texto, nome, pixPagamento });
    }

    // Verifica se pagamento MP foi confirmado
    let pagamentoMp = null;
    try {
      pagamentoMp = await db.prepare('SELECT payment_id FROM presentes WHERE status = ?').get('aguardando');
    } catch {}

    // Marca como enviada
    await db.prepare('UPDATE presentes SET status = ? WHERE payment_id = ?')
      .run('processado', pagamentoMp?.payment_id || null);

    qrAtivo = false;
    setTimeout(() => { qrAtivo = true; }, 8000); // reinicia QR após 8s

    res.json({ ok: true, mensagem: texto, nome: nome });
  } catch (err) {
    console.error(err);
    res.status(500).json({ erro: err.message });
  }
});

app.post('/api/pix', async (req, res) => {
  // Webhook/callback do Mercado Pago para confirmação de pagamento
  const { status, payment_id } = req.body;
  if (status === 'AUTHORIZED' || status === 'PENDING' || status === 'CONFIRMED') {
    await db.prepare('INSERT OR REPLACE INTO presentes (payment_id, valor, status)')
      .run(payment_id, 0, status)
      .then(() => {
        // Só considera confirmado após CONFIRMED (webhook real da MP)
      });
    res.json({ ok: true });
  } else {
    res.json({ ok: false, status });
  }
});

// Endpoint para gerar novo QR Pix (pode ser chamado por background)
app.get('/api/qrcode-pix', async (req, res) => {
  const chave = crypto.randomUUID(); // chave única do QR Pix
  try {
    const d = await fetch('https://api.mercadopago.com/v1/pix', {
      method: 'POST',
      headers: { Authorization: `Bearer ${process.env.MERCADO_PASON_ACCESS_TOKEN}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ amount: 50, currency_id: 'BRL', metadata: { evento: 'presente-casamento', chave: chave } }),
    });
    const data = await d.json();
    res.json({ chavePix: data.chave, url: data.url });
  } catch (e) {
    res.status(500).json({ erro: e.message });
  }
});

server.listen(Number(process.env.PORT || 3000), () => {
  console.log(`✅ Servidor rodando em http://localhost:${process.env.PORT || 3000}`);
});

// Background: tenta recriar QR Pix a cada 60s
setInterval(async () => {
  try {
    const resp = await fetch(`${process.env.SITE_URL}/api/qrcode-pix`, { method: 'GET' });
    const data = await resp.json();
    // Você pode expor isso numa variável global JS
    global.__qrData = data;
  } catch (e) {
    console.warn('Falhou ao regenerar QR:', e.message);
  }
}, 60000);

module.exports = app;
```

