## 8️⃣ `public/main.js` — Lógica da tela principal

```js
const socket = io();

// Busca dados iniciais via WS
socket.on('connect', () => {
  // alternativa: pedir via fetch
  fetch('/api/status')
    .then(r => r.json())
    .then(d => carregarTudo(d));
});

function carregarTudo(data = {}) {
  const qrEl = document.getElementById('qr-img');
  const areaQr = document.getElementById('area-qr');
  const nPresentes = document.getElementById('n-presentes');
  const listaPat = document.getElementById('lista-patrocinadores');
  const listaMsg = document.getElementById('lista-mensagens');

  if (data.ultimas) {
    listaMsg.innerHTML = data.ultimas.map(m => `
      <div class="msg-item">
        "${m.texto}"
        <span class="quem">${m.nome_enviador || 'Anônimo'}</span>
      </div>
    `).join('');
  }

  if (data.qr) {
    // Aqui você injeta a imagem do QR Pix gerado
    const img = new Image();
    img.onload = () => { qrEl.src = data.qr.url; };
    img.onerror = () => renderQrFallback();
    areaQr.style.display = '';
  } else {
    renderQrFallback();
  }

  nPresentes.textContent = data.totalPresentes || 0;

  // Ranking patrocinadores (exemplo estático, troque por API)
  listaPat.innerHTML = [
    '<li class="pat"><strong>Bella Joias</strong><span>Top patrocinador</span></li>',
    '<li class="pat"><strong>Cerimonial Amor</strong><span>Oficial do dia</span></li>',
    '<li class="pat"><strong>Flores & Cia</strong><span>Arranjos</span></li>',
  ].join('');

  // Escuta status do socket
  socket.on('status', (d) => {
    nPresentes.textContent = d.ultimas?.length || 0;
    if (!d.qr) renderQrFallback();
    carregarTudo(d.ultimas);
  });
}

function renderQrFallback() {
  // Gera QR fallback com base64 de uma imagem simples (ou link de imagem fixa)
  const canvas = document.createElement('canvas');
  canvas.width = 500; canvas.height = 500;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = '#fff';
  ctx.fillRect(0,0,500,500);
  // aqui você usaria uma lib como qrcode/libqrcode para gerar de verdade
  // Ex.: qrcode.toCanvas(canvas, chavePixUrl);
  // Para agora, coloque uma imagem estática de exemplo:
  const ex = new Image('https://api.qrserver.com/v1/qr?url=https://seusite.com/presente&size=500x500');
  ex.onload = () => { ctx.drawImage(ex, 0, 0, 500, 500); };
  // fallback imediato caso falhe:
  ctx.font = 'bold 40px Arial';
  ctx.fillText('Escaneie o QR Code', 100, 250);
  document.getElementById('area-qr').appendChild(canvas);
}
```

